  draw_queue.clear();
  world_candidates(queues,WorldRenderPass::Glass,[&](GPU& mesh,size_t){draw_queue.push_back(&mesh);});
  std::stable_sort(draw_queue.begin(),draw_queue.end(),[&](GPU*a,GPU*b){return dot(a->center-eye,a->center-eye)>dot(b->center-eye,b->center-eye);});
  for(auto* packet:draw_queue)mesh(*packet,identity());
