DiagnosticPixels Renderer::capture_performance_frame(){
 if(p_->lost)return {0,0,{},"graphics_device_unavailable"};
 if(p_->width<=0||p_->height<=0||uint64_t(p_->width)*p_->height>16777216)
  return {0,0,{},"backbuffer_exceeds_capture_limit"};
 struct ReadState {
  GLint framebuffer=0,alignment=0;
  ReadState(){
   glGetIntegerv(GL_READ_FRAMEBUFFER_BINDING,&framebuffer);
   glGetIntegerv(GL_PACK_ALIGNMENT,&alignment);
   gl.BindFramebuffer(GL_READ_FRAMEBUFFER,0);
  }
  ~ReadState(){
   glPixelStorei(GL_PACK_ALIGNMENT,alignment);
   gl.BindFramebuffer(GL_READ_FRAMEBUFFER,framebuffer);
  }
 } read_state;
 PhotoPixels image;
 if(!p_->photo_gpu.capture(p_->d,image))return {0,0,{},p_->photo_gpu.last_error()};
 return {image.width,image.height,std::move(image.argb),{}};
}

